const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const idbVault = {
  dbp: null,
  open() {
    if (this.dbp) return this.dbp;
    this.dbp = new Promise((res) => {
      try {
        if (!window.indexedDB) return res(null);
        const r = indexedDB.open("niubision-vault", 1);
        r.onupgradeneeded = () => {
          if (!r.result.objectStoreNames.contains("kv")) r.result.createObjectStore("kv");
        };
        r.onsuccess = () => res(r.result);
        r.onerror = () => res(null);
      } catch (e) { res(null); }
    });
    return this.dbp;
  },
  async put(k, v) {
    try {
      const db = await this.open();
      if (!db) return false;
      return await new Promise((ok) => {
        const tx = db.transaction("kv", "readwrite");
        tx.objectStore("kv").put(v, k);
        tx.oncomplete = () => ok(true);
        tx.onerror = () => ok(false);
      });
    } catch (e) { return false; }
  },
  async get(k) {
    try {
      const db = await this.open();
      if (!db) return undefined;
      return await new Promise((ok) => {
        const tx = db.transaction("kv", "readonly");
        const q = tx.objectStore("kv").get(k);
        q.onsuccess = () => ok(q.result);
        q.onerror = () => ok(undefined);
      });
    } catch (e) { return undefined; }
  }
};
const store = {
  get(k, d) { try { return JSON.parse(localStorage.getItem(k)) ?? d; } catch { return d; } },
  set(k, v) {
    let ok = false;
    try { localStorage.setItem(k, JSON.stringify(v)); ok = true; }
    catch (e) {
      try { if (k !== "nb_clients") localStorage.removeItem("nb_photos"); } catch (e2) {}
      if (!store._warned) {
        store._warned = true;
        toast("Espacio lleno en el navegador. Clientes y códigos quedan en la copia segura.");
      }
    }
    try { idbVault.put(k, v); } catch (e) {}
    return ok;
  }
};

