  try {
    if (typeof isUiPreviewHost === "function" && isUiPreviewHost()
      && String(report.accessCode || "").replace(/\D/g, "") === (typeof PREVIEW_DEMO_CODE !== "undefined" ? PREVIEW_DEMO_CODE : "240101")) {
      return { ok: true, preview: true };
    }
  } catch (e) {}
