function pickAiEx(needles, used, place, avoid) {
  const list = state.exercises || [];
  const home = /casa/i.test(place || "");
  const av = String(avoid || "").toLowerCase();
  const scored = list.map((e) => {
    if (used.has(e.id)) return null;
    const hay = ((e.name || "") + " " + (e.muscles || []).join(" ") + " " + (e.equipment || "") + " " + (e.equipmentEs || "")).toLowerCase();
    if (av && hay.indexOf(av) >= 0) return null;
    if (home && /barbell|smith|machine|cable|leverage/i.test(e.equipment || "")) return null;
    let s = 0;
    needles.forEach((n) => { if (hay.indexOf(n) >= 0) s += 2; });
    if (/beginner|inicio/i.test(e.level || "") || /inicio/i.test(e.levelEs || "")) s += 1;
    return s > 0 ? { e, s } : null;
  }).filter(Boolean).sort((a, b) => b.s - a.s);
  const hit = scored[0] && scored[0].e;
  if (!hit) return null;
  used.add(hit.id);
  return hit;
}
function buildAiRoutine(opts) {
  const days = Math.max(2, Math.min(5, parseInt(opts.days, 10) || 3));
  const minutes = parseInt(opts.minutes, 10) || 45;
  const place = opts.place || "Gimnasio";
  const goal = opts.goal || "fuerza";
  const avoid = opts.avoid || "";
  const used = new Set();
  const templates = {
    2: [
      { title: "Día 1 · Empuje y pierna", slots: [["squat", "quad", "goblet"], ["bench", "chest", "press"], ["row", "back"], ["shoulder", "press"], ["plank", "abdominal"]] },
      { title: "Día 2 · Bisagra y tracción", slots: [["deadlift", "romanian", "hinge"], ["pulldown", "lat", "row"], ["lunge", "split"], ["raise", "shoulder"], ["superman", "back"]] }
    ],
    3: [
      { title: "Día 1 · Sentadilla y empuje", slots: [["squat", "quad"], ["bench", "chest"], ["row", "back"], ["plank", "abdominal"]] },
      { title: "Día 2 · Bisagra y tracción", slots: [["deadlift", "romanian"], ["pulldown", "lat"], ["shoulder", "press"], ["superman", "back"]] },
      { title: "Día 3 · Unilateral y tronco", slots: [["lunge", "split"], ["hip", "glute"], ["curl", "bicep"], ["extension", "tricep"], ["plank", "abdominal"]] }
    ],
    4: [
      { title: "Día 1 · Pierna", slots: [["squat", "quad"], ["lunge", "split"], ["romanian", "hamstring"], ["calf", "raise"]] },
      { title: "Día 2 · Empuje", slots: [["bench", "chest"], ["shoulder", "press"], ["tricep", "extension"], ["raise", "lateral"]] },
      { title: "Día 3 · Tracción", slots: [["row", "back"], ["pulldown", "lat"], ["curl", "bicep"], ["face", "rear"]] },
      { title: "Día 4 · Cadera y tronco", slots: [["hip", "glute"], ["deadlift", "romanian"], ["plank", "abdominal"], ["superman", "back"]] }
    ],
    5: [
      { title: "Día 1 · Cuádriceps", slots: [["squat", "quad"], ["lunge", "split"], ["extension", "leg"]] },
      { title: "Día 2 · Empuje", slots: [["bench", "chest"], ["shoulder", "press"], ["tricep"]] },
      { title: "Día 3 · Espalda", slots: [["row", "back"], ["pulldown", "lat"], ["face"]] },
      { title: "Día 4 · Bisagra", slots: [["deadlift", "romanian"], ["hip", "glute"], ["curl", "leg"]] },
      { title: "Día 5 · Brazos y tronco", slots: [["curl", "bicep"], ["extension", "tricep"], ["plank", "abdominal"], ["raise", "lateral"]] }
    ]
  };
  const daysPlan = (templates[days] || templates[3]).map((d) => {
    const items = [];
    d.slots.forEach((needles) => {
      const ex = pickAiEx(needles, used, place, avoid);
      if (!ex) return;
      const rest = /plank|abdominal|raise|curl/i.test(ex.name) ? 45 : 90;
      const sets = minutes >= 60 ? 4 : 3;
      items.push({ name: ex.name, sets, reps: "8–10", rest, exId: ex.id });
    });
    return { title: d.title, items };
  }).filter((d) => d.items.length);
  const id = "ai-" + Date.now();
  return {
    id,
    name: "Biblioteca · " + goal + " · " + days + " días",
    days,
    minutes,
    level: goal === "inicio" ? "Inicio" : "Intermedio",
    place,
    goal: "Programa generado con la biblioteca NiuBision. El entrenador puede ajustarlo.",
    evidence: "Volumen por grupo, 2 o más veces por semana cuando el split lo permite. Criterio ACSM de progresión.",
    ai: true,
    daysPlan
  };
}
function saveAiRoutine(rt, client) {
  state.customRoutines = state.customRoutines || [];
  state.customRoutines.push(rt);
  if (client && state.role === "coach") client.routine = rt.id;
  persist();
}
function emailReceipt(row) {
  if (!row) return;
  const payload = {
    date: row.date,
    name: row.name,
    plan: row.plan,
    amount: row.amount,
    method: row.method,
    status: row.status || "recibido",
    accessCode: row.accessCode || "",
    email: row.email || (state.profile && state.profile.email) || ""
  };
  const bases = apiBases();
  const send = (base) => cloudGet(base + "/receipt", {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify(payload)
  }).catch(() => null);
  Promise.all(bases.slice(0, 2).map(send)).catch(() => {});
  const text = "Recibo NiuBision\n" + (payload.name || "") + " · " + (payload.plan || "") + " · " + (payload.amount || "") + " USD · " + (payload.method || "");
  ntfyPost("niubision-recibo", text, { Title: "Recibo NiuBision", Email: "miguel.morales9@gmail.com" });
  if (payload.email && payload.email !== "miguel.morales9@gmail.com") {
    ntfyPost("niubision-recibo", text, { Title: "Recibo NiuBision", Email: payload.email });
  }
}
function printReceipt(row) {
  const html = "<!DOCTYPE html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>Recibo NiuBision</title><style>body{font-family:Georgia,serif;padding:28px;color:#121018;max-width:420px} h1{font-size:22px;margin:0 0 4px} .muted{color:#666;font-size:13px} .code{font-size:32px;letter-spacing:.12em;text-align:center;margin:16px 0} table{width:100%;margin-top:16px;border-collapse:collapse} td{padding:6px 0;border-bottom:1px solid #eee;font-size:14px} td:last-child{text-align:right}</style></head><body><h1>NiuBision</h1><p class='muted'>See the work. Enjoy the day.</p><p><strong>Recibo</strong></p><table><tr><td>Fecha</td><td>" + escapeHtml(row.date) + "</td></tr><tr><td>Cliente</td><td>" + escapeHtml(row.name || "Cliente") + "</td></tr><tr><td>Concepto</td><td>" + escapeHtml(row.plan) + "</td></tr>" + (ivuSplit(row.amount) ? "<tr><td>Base</td><td>" + ivuSplit(row.amount).base + " USD</td></tr><tr><td>IVU (11.5 %)</td><td>" + ivuSplit(row.amount).ivu + " USD</td></tr>" : "") + "<tr><td>Total, IVU incluido</td><td>" + escapeHtml(String(row.amount || "—")) + " USD</td></tr><tr><td>Método</td><td>" + escapeHtml(row.method) + "</td></tr><tr><td>Estado</td><td>" + escapeHtml(row.status || "iniciado") + "</td></tr>" + (row.accessCode ? "<tr><td>Código</td><td>" + escapeHtml(row.accessCode) + "</td></tr>" : "") + "</table>" + (row.accessCode ? "<p class='code'>" + escapeHtml(row.accessCode) + "</p><p class='muted'>Código de acceso de 6 dígitos. Válido cuando el pago está hecho.</p>" : "") + "<p class='muted' style='margin-top:18px'>Precio final, IVU (11.5 %) incluido. NiuBision no guarda tarjetas. El dinero sale por PayPal, ATH Móvil o tarjeta (Stripe). Este recibo confirma el registro en el estudio.</p></body></html>";
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const w = window.open(url, "_blank");
  if (!w) { toast("Permita ventanas emergentes para el recibo"); return; }
  setTimeout(() => { try { w.print(); } catch (e) {} }, 400);
}
