function vigencyHtml(c) {
  if (!c) return "";
  const st = clientStatus(c);
  const left = daysLeft(c);
  const sess = sessionsLeft(c);
  const bits = [];
  bits.push(statusLabel(st));
  if (c.startDate && c.endDate) bits.push(c.startDate + " → " + c.endDate);
  if (left != null) bits.push(left >= 0 ? left + " días" : "venció");
  if (sess != null) bits.push(sess + " sesiones");
  return bits.join(" · ");
}
