      if (/rutina con ia/i.test(p.plan || "")) {
        p.status = "recibido";
        state.aiCredits = (state.aiCredits || 0) + 1;
        persist();
        toast("Pago recibido. Crédito de IA listo");
        openReceipt(p);
        render();
        return;
      }
      let cl = state.clients.find((x) => x.id === p.clientId) || (state.clients || []).find((x) => x.name === p.name);
      if (!cl && p.name) {
        cl = { id: p.clientId || ("c" + Date.now()), name: p.name, plan: p.plan || "Estándar", routine: "", unpaid: true };
        state.clients.push(cl);
      }
      const done = await confirmClientPaid(cl, p.method);
      if (!done) { render(); return; }
      toast(done.code ? "Pago recibido. Código " + done.code : "Pago recibido");
      render();
      if (done.client && done.code && autoCodeOn()) showShare(done.client);
      else if (p) openReceipt(p);
