function ensureRenewals() {
  let added = false;
  (state.clients || []).forEach((c) => {
    if (!c) return;
    normalizeClient(c);
    const st = clientStatus(c);
    if (st !== "por vencer" && st !== "vencido") return;
    const inv = "ren-" + c.id;
    const has = (state.payments || []).some((p) => p && (
      p.invoice === inv ||
      (p.clientId === c.id && p.status !== "recibido") ||
      (p.name && cleanName(p.name) === cleanName(c.name) && p.status === "renovar")
    ));
    if (has) return;
    const info = planPriceOf(c.plan);
    state.payments = state.payments || [];
    state.payments.push({
      id: "p" + Date.now() + Math.floor(Math.random() * 99),
      date: todayKey(),
      plan: c.plan,
      amount: info.amount,
      method: "",
      status: "renovar",
      name: c.name,
      clientId: c.id,
      invoice: inv,
      ref: "NB-R" + String(c.id).replace(/\D/g, "").slice(-4)
    });
    added = true;
  });
  if (added) persist();
}
function dedupePayments(list) {
  const map = {};
  const rank = (x) => (x && x.status === "recibido" ? 3 : x && x.status === "iniciado" ? 2 : 1);
  (list || []).forEach((p) => {
    if (!p || typeof p !== "object") return;
    const who = (p.clientId || "") + "|" + cleanName(p.name || "");
    const inv = String(p.invoice || "");
    const k = (inv.indexOf("ren-") === 0 && p.status !== "recibido")
      ? "ren:" + inv
      : ("p:" + who + "|" + (p.date || "") + "|" + String(p.amount || ""));
    const prev = map[k];
    if (!prev || rank(p) > rank(prev)) map[k] = prev ? Object.assign({}, prev, p, { status: rank(p) >= rank(prev) ? p.status : prev.status }) : p;
    else if (prev && rank(p) === rank(prev) && String(p.id || "") > String(prev.id || "")) map[k] = Object.assign({}, prev, p);
  });
  const rows = Object.keys(map).map((k) => map[k]);
  const got = {};
  rows.forEach((p) => {
    if (p.status !== "recibido") return;
    got[(p.clientId || "") + "|" + cleanName(p.name || "") + "|" + (p.date || "") + "|" + String(p.amount || "")] = 1;
  });
  return rows.filter((p) => {
    if (p.status === "recibido") return true;
    const k = (p.clientId || "") + "|" + cleanName(p.name || "") + "|" + (p.date || "") + "|" + String(p.amount || "");
    return !got[k];
  });
}
function recentInbox() {
  const seen = {};
  const out = [];
  const cut = Date.now() - 48 * 3600 * 1000;
  const idx = livingClientIndex();
  (state.inbox || []).slice().reverse().forEach((n) => {
    if (!n) return;
    if (n.at && n.at < cut) return;
    if (isRevoked(n.accessCode, n.clientId)) return;
    if (n.type === "code" || inboxNoteHidden(n)) return;
    if (!docBelongsToLiving(n, idx)) return;
    const k = (n.type || "n") + ":" + (n.clientId || cleanName(n.name || "") || n.id);
    if (seen[k]) return;
    seen[k] = 1;
    out.push(n);
  });
  return out.slice(0, 3);
}
