function stashPendingCode(raw) {
  const digits = String(raw || "").replace(/\D/g, "").slice(0, 6);
  if (digits.length === 6) state._pendingCode = digits;
}
function applyHash() {
  const q = new URLSearchParams(location.search || "");
  const viewQ = q.get("view");
  if (viewQ && /^(price|about|coach|social|work|home|people)$/.test(viewQ)) {
    if (!state.role) state.role = "guest";
    state.view = viewQ;
    if (state.role === "guest") { state.splash = false; state._deepLinked = true; }
  }
  const planQ = String(q.get("plan") || "").replace(/[^A-Za-z0-9]/g, "");
  if (planQ && viewQ === "price") state._planAnchor = planQ.toLowerCase() === "estandarfundador" ? "estandarFundador" : planQ.toLowerCase();
  stashPendingCode(q.get("c") || q.get("code"));
  const raw = String(location.hash || "").replace(/^#/, "");
  if (!raw) return;
  const params = new URLSearchParams(raw.indexOf("=") >= 0 ? raw : "");
  const blob = params.get("n") || params.get("nube");
  if (blob) {
    store.set("nb_blob_id", blob);
    if (state.settings) state.settings.cloudId = blob;
  }
  const ticket = params.get("t") || params.get("ticket");
  if (ticket) {
    const decoded = decodeTicket(ticket);
    if (decoded && decoded.accessCode) stashPendingCode(decoded.accessCode);
    return;
  }
  const code = params.get("c") || params.get("code");
  if (code) {
    stashPendingCode(code);
    return;
  }
  if (/^NB[12]\|/i.test(raw)) {
    const assigned = parseClientCode(raw);
    if (assigned && assigned.accessCode) stashPendingCode(assigned.accessCode);
  }
}

function guardLogoMedia(el) {
  if (!el) return;
  const prevent = (e) => e.preventDefault();
  el.addEventListener("contextmenu", prevent);
  el.addEventListener("dragstart", prevent);
  el.style.webkitTouchCallout = "none";
  el.style.touchAction = "none";
  const img = el.querySelector("img");
  if (img) {
    img.draggable = false;
    img.setAttribute("draggable", "false");
    img.style.webkitTouchCallout = "none";
    img.style.touchAction = "none";
    img.addEventListener("contextmenu", prevent);
    img.addEventListener("dragstart", prevent);
  }
}


