function warmupIntro() {
  if (warmupIntro.el) return warmupIntro.el;
  const v = document.createElement("video");
  v.muted = true;
  v.playsInline = true;
  v.setAttribute("playsinline", "");
  v.setAttribute("webkit-playsinline", "");
  v.preload = "auto";
  v.poster = "/intro-poster.jpg";
  v.src = "/intro.mp4?v=3";
  try { v.load(); } catch (e) {}
  warmupIntro.el = v;
  return v;
}
function playIntro() {
  return new Promise((resolve) => {
    if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      resolve();
      return;
    }
    const v = warmupIntro();
    try { v.pause(); v.currentTime = 0; } catch (e) {}
    const host = document.createElement("div");
    host.className = "intro-play";
    host.setAttribute("aria-label", "NiuBision");
    host.appendChild(v);
    (document.body || document.documentElement).appendChild(host);
    let done = false;
    let canSkip = false;
    const finish = () => {
      if (done) return;
      done = true;
      host.classList.add("out");
      host.style.pointerEvents = "none";
      setTimeout(() => {
        try { if (v.parentNode === host) host.removeChild(v); } catch (e2) {}
        try { host.remove(); } catch (e3) {}
        resolve();
      }, 280);
    };
    setTimeout(() => { canSkip = true; }, 500);
    host.addEventListener("pointerdown", (e) => { if (!canSkip) return; e.preventDefault(); finish(); });
    v.addEventListener("ended", finish, { once: true });
    v.addEventListener("error", () => setTimeout(finish, 300), { once: true });
    const tryPlay = () => { v.play().catch(() => {}); };
    if (v.readyState >= 2) tryPlay();
    else v.addEventListener("canplay", tryPlay, { once: true });
    tryPlay();
    setTimeout(finish, 7000);
  });
}

function playRing() {
  const splash = $("#splash");
  const ringEl = splash && splash.querySelector(".ring-hold");
  const logo = splash && splash.querySelector(".splash-logo");
  const ringBox = ringEl ? ringEl.getBoundingClientRect() : null;
  const from = logo ? logo.getBoundingClientRect() : null;
  const box = (ringBox && ringBox.width > 40) ? ringBox : from;
  const ox = box ? box.left + box.width / 2 : window.innerWidth / 2;
  const oy = box ? box.top + box.height / 2 : window.innerHeight * 0.42;
  const startD = box && box.width > 40 ? box.width : 220;
  const corners = [[0, 0], [window.innerWidth, 0], [0, window.innerHeight], [window.innerWidth, window.innerHeight]];
  let far = 0;
  corners.forEach(function (pt) {
    far = Math.max(far, Math.hypot(pt[0] - ox, pt[1] - oy));
  });
  const grow = (far + 36) / Math.max(8, startD / 2 - 6);
  const host = document.createElement("div");
  host.id = "nbRingReveal";
  host.className = "nb-ring-reveal";
  host.setAttribute("aria-hidden", "true");
  host.style.setProperty("--ox", ox + "px");
  host.style.setProperty("--oy", oy + "px");
  host.style.setProperty("--d", startD + "px");
  host.style.setProperty("--grow", String(grow));
  let orb = null;
  if (logo && from && from.width > 0) {
    orb = logo.cloneNode(true);
    orb.className = "nb-ring-orb";
    orb.removeAttribute("id");
    orb.alt = "";
    orb.style.left = from.left + "px";
    orb.style.top = from.top + "px";
    orb.style.width = from.width + "px";
    orb.style.height = from.height + "px";
    host.appendChild(orb);
  }
  const hole = document.createElement("div");
  hole.className = "nb-ring-hole";
  host.appendChild(hole);
  document.body.appendChild(host);
  state.splash = false;
  store.set("nb_seen_cover", true);
  store.set("nb_seen_intro", true);
  render();
  const cover = document.querySelector(".cover-hybrid");
  const coverImg = cover && cover.querySelector(".splash-logo");
  if (cover) cover.classList.add("nb-held");
  if (coverImg) coverImg.style.visibility = "hidden";
  const to = coverImg ? coverImg.getBoundingClientRect() : null;
  const ms = 980;
  const ease = "cubic-bezier(0.65, 0.05, 0.18, 1)";
  let holeAnim = null;
  let orbAnim = null;
  let settled = false;
  /* Tear down only after the ring has faded. Removing nb-held used to restart
     .screen { animation: rise }, which snaps the cover from opacity 0. */
  const settle = () => {
    if (settled) return;
    settled = true;
    const landed = coverImg ? coverImg.getBoundingClientRect() : to;
    if (orb && landed && landed.width > 0) {
      orb.style.left = landed.left + "px";
      orb.style.top = landed.top + "px";
      orb.style.width = landed.width + "px";
      orb.style.height = landed.height + "px";
      orb.style.opacity = "1";
      orb.style.filter = "drop-shadow(0 0 22px rgba(255,138,31,.18))";
    }
    hole.style.opacity = "0";
    hole.style.transform = "translate(-50%, -50%) scale(" + grow + ")";
    hole.style.willChange = "auto";
    try { if (holeAnim) holeAnim.cancel(); } catch (e) {}
    try { if (orbAnim) orbAnim.cancel(); } catch (e2) {}
    if (coverImg) coverImg.style.visibility = "";
    if (cover) cover.style.animation = "none";
    requestAnimationFrame(function () {
      if (orb) { try { orb.remove(); } catch (e3) {} }
      try { host.remove(); } catch (e4) {}
      if (cover) cover.classList.remove("nb-held");
    });
  };
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      host.classList.add("open");
      holeAnim = hole.animate([
        { transform: "translate(-50%, -50%) scale(1)", opacity: 1 },
        { transform: "translate(-50%, -50%) scale(" + grow + ")", opacity: 1, offset: 0.9 },
        { transform: "translate(-50%, -50%) scale(" + grow + ")", opacity: 0 }
      ], { duration: ms, easing: ease, fill: "forwards" });
      if (orb && from && to && to.width > 0) {
        orbAnim = orb.animate([
          { left: from.left + "px", top: from.top + "px", width: from.width + "px", height: from.height + "px", opacity: 1 },
          { left: to.left + "px", top: to.top + "px", width: to.width + "px", height: to.height + "px", opacity: 1, offset: 0.42 },
          { left: to.left + "px", top: to.top + "px", width: to.width + "px", height: to.height + "px", opacity: 1 }
        ], { duration: ms, easing: ease, fill: "forwards" });
      }
      const pending = [holeAnim.finished];
      if (orbAnim) pending.push(orbAnim.finished);
      Promise.all(pending).then(settle).catch(settle);
      setTimeout(settle, ms + 80);
    });
  });
}

function bindSplash() {
  const wrap = $("#holdLogo");
  const ring = $("#holdRing") || $(".ring-progress") || $(".ring circle");
  let hold = 0, ticking = false, raf, gone = false;
  const paintRing = (v) => {
    if (!ring) return;
    ring.style.strokeDashoffset = String(100 - v);
    wrap && wrap.style.setProperty("--hold", String(v));
  };
  paintRing(0);
  const go = () => {
    if (gone) return;
    gone = true;
    window.removeEventListener("pointerup", up);
    wrap.removeEventListener("pointerdown", down);
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) {
      state.splash = false;
      store.set("nb_seen_cover", true);
      store.set("nb_seen_intro", true);
      render();
      return;
    }
    playRing();
  };
  const step = (on) => {
    ticking = on;
    cancelAnimationFrame(raf);
    const loop = () => {
      hold = Math.max(0, Math.min(100, hold + (ticking ? 2.4 : -3)));
      paintRing(hold);
      wrap.classList.toggle("charged", hold > 12);
      wrap.classList.toggle("holding", ticking && hold > 0);
      if (hold >= 100) { go(); return; }
      if (hold > 0 || ticking) raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
  };
  const down = (e) => { e.preventDefault(); step(true); };
  const up = () => step(false);
  wrap.addEventListener("pointerdown", down);
  window.addEventListener("pointerup", up);
  wrap.addEventListener("click", () => { if (hold < 100) toast("Mantenga pulsado el logo hasta llenar el anillo"); });
}

function enterClient(view) {
  const code = String((state.profile && state.profile.accessCode) || "").replace(/\D/g, "");
  const live = findByAccessCode(code);
  if (!live || isRevoked(code, live.id) || !clientSeatOpen()) {
    clearClientSeat();
    persist();
    toast("Ese acceso ya no vale. Pague de nuevo para recibir un código.");
    openCodeEntry();
    return;
  }
  state.role = "client";
  state.view = view || "work";
  persist();
  render();
  if (!waiverSigned()) setTimeout(() => openWaiver(() => render()), 400);
  if (isOnline() && code.length === 6) {
    lookupAccess(code).then((hit) => {
      if (hit) return;
      if (isRevoked(code, state.profile.clientId) || !clientSeatOpen()) {
        lockOutClient();
        render();
      }
    }).catch(() => {});
  }
}
