function copyText(text) {
  const area = document.createElement("textarea");
  area.value = text;
  area.setAttribute("readonly", "");
  area.style.position = "fixed";
  area.style.left = "-9999px";
  document.body.appendChild(area);
  area.select();
  area.setSelectionRange(0, text.length);
  let ok = false;
  try { ok = document.execCommand("copy"); } catch (e) {}
  document.body.removeChild(area);
  if (ok) return Promise.resolve(true);
  if (navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(text).then(() => true).catch(() => false);
  }
  return Promise.resolve(false);
}
function bindSigPad(canvas) {
  if (!canvas) return { dirty: () => false, clear() {}, unbind() {} };
  const ctx = canvas.getContext("2d");
  ctx.strokeStyle = "#f7f1e8";
  ctx.lineWidth = 3;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  let draw = false, dirty = false;
  const pos = (e) => {
    const r = canvas.getBoundingClientRect();
    const pt = (e.touches && e.touches[0]) || e;
    const w = r.width || 1, h = r.height || 1;
    return { x: (pt.clientX - r.left) * (canvas.width / w), y: (pt.clientY - r.top) * (canvas.height / h) };
  };
  const start = (e) => {
    e.preventDefault();
    draw = true;
    dirty = true;
    try { if (e.pointerId != null) canvas.setPointerCapture(e.pointerId); } catch (err) {}
    const p = pos(e);
    ctx.beginPath();
    ctx.moveTo(p.x, p.y);
    ctx.lineTo(p.x + 0.8, p.y + 0.8);
    ctx.stroke();
  };
  const move = (e) => {
    if (!draw) return;
    e.preventDefault();
    const p = pos(e);
    ctx.lineTo(p.x, p.y);
    ctx.stroke();
    dirty = true;
  };
  const end = () => { draw = false; };
  canvas.addEventListener("pointerdown", start);
  canvas.addEventListener("pointermove", move);
  canvas.addEventListener("pointerup", end);
  canvas.addEventListener("pointercancel", end);
  canvas.addEventListener("pointerleave", end);
  window.addEventListener("pointerup", end);
  return {
    dirty: () => dirty,
    clear() { ctx.clearRect(0, 0, canvas.width, canvas.height); dirty = false; },
    unbind() {
      canvas.removeEventListener("pointerdown", start);
      canvas.removeEventListener("pointermove", move);
      canvas.removeEventListener("pointerup", end);
      canvas.removeEventListener("pointercancel", end);
      canvas.removeEventListener("pointerleave", end);
      window.removeEventListener("pointerup", end);
    }
  };
}
